          const Icon = link.icon;
          const isActive = location.pathname === link.path || 
            (link.path === '/admin/doctor-verification' && location.pathname.startsWith('/admin/doctors')) ||
            (link.path === '/admin/reports' && location.pathname === '/admin/analytics');
