                        <Button variant="danger" size="xs"><XCircle className="w-3 h-3 mr-1" /> Reject</Button>
                      </div>
                    </div>
                  </motion.div>
                ))}
              </div>
            </GlassmorphicCard>
          </motion.div>
        </div>
      </div>
    </div>
  );
};

