# ============================================
# ADMIN ROUTES
# ============================================
@app.route('/api/v1/admin/users', methods=['GET'])
@token_required
@role_required('admin', 'super_admin')
def admin_get_users():
    users = query("""SELECT u.*, r.name as role_name
                    FROM users u
                    LEFT JOIN user_roles ur ON ur.user_id = u.id AND ur.is_primary = TRUE
                    LEFT JOIN roles r ON r.id = ur.role_id
                    ORDER BY u.created_at DESC""")
    return jsonify(users)

@app.route('/api/v1/admin/doctors/pending', methods=['GET'])
@token_required
@role_required('admin', 'super_admin')
def admin_pending_doctors():
    doctors = query("""SELECT u.*, dp.*
                      FROM doctor_profiles dp
                      JOIN users u ON u.id = dp.user_id
                      WHERE dp.is_verified = FALSE
                      ORDER BY dp.created_at ASC""")
    return jsonify(doctors)

@app.route('/api/v1/admin/doctors/<doctor_id>/verify', methods=['POST'])
@token_required
@role_required('admin', 'super_admin')
def admin_verify_doctor(doctor_id):
    query("UPDATE doctor_profiles SET is_verified = TRUE, verified_by = %s, verified_at = NOW() WHERE user_id = %s",
          (request.user['id'], doctor_id), fetch=False)
    return jsonify({'message': 'Doctor verified'})

@app.route('/api/v1/admin/analytics/overview', methods=['GET'])
@token_required
@role_required('admin', 'super_admin')
def admin_analytics():
    total_users = query("SELECT COUNT(*) as count FROM users")[0]['count']
    total_doctors = query("SELECT COUNT(*) as count FROM doctor_profiles")[0]['count']
    total_hospitals = query("SELECT COUNT(*) as count FROM hospitals")[0]['count']
    total_pharmacies = query("SELECT COUNT(*) as count FROM pharmacies")[0]['count']
    total_appointments = query("SELECT COUNT(*) as count FROM appointments")[0]['count']
    total_patients = query("SELECT COUNT(*) as count FROM users")[0]['count']
    return jsonify({
        'total_users': total_users,
        'total_doctors': total_doctors,
        'total_hospitals': total_hospitals,
        'total_pharmacies': total_pharmacies,
        'total_appointments': total_appointments,
        'total_patients': total_patients
    })

